import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyHoaDon = () => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);

    const years = [2024, 2025, 2026];
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    const isCurrentOrFuture =
        selectedYear > currentYear ||
        (selectedYear === currentYear && selectedMonth >= currentMonth);

    const totalReceived = isCurrentOrFuture ? 0 : (5000000 * 45);

    return (
        <div style={{
            flex: 1, // ✅ thay vì 100vh
            display: 'flex',
            flexDirection: 'column',
            backgroundImage: `url(${chatBgImg})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            padding: '20px',
            boxSizing: 'border-box',
            minHeight: 0 // ✅ QUAN TRỌNG
        }}>

            {/* Card chính */}
            <div style={{
                flex: 1,
                display: 'flex',
                flexDirection: 'column',
                backgroundColor: 'rgba(255,255,255,0.1)',
                borderRadius: '30px',
                minHeight: 0 // ✅ QUAN TRỌNG
            }}>

                {/* Header */}
                <div style={{
                    padding: '20px',
                    color: '#fff',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    flexShrink: 0
                }}>
                    <h2 style={{ margin: 0 }}>Quản lý hoá đơn</h2>

                    <div style={{ display: 'flex', gap: '10px' }}>
                        <select value={selectedMonth}
                            onChange={(e) => setSelectedMonth(parseInt(e.target.value))}
                            style={{ padding: '8px', borderRadius: '10px' }}>
                            {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                        </select>

                        <select value={selectedYear}
                            onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                            style={{ padding: '8px', borderRadius: '10px' }}>
                            {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                        </select>
                    </div>
                </div>

                {/* Body */}
                <div style={{
                    flex: 1,
                    display: 'flex',
                    gap: '30px',
                    padding: '0 20px 20px 20px',
                    minHeight: 0 // ✅ QUAN TRỌNG
                }}>

                    {/* LEFT */}
                    <div style={{
                        width: '210px',
                        display: 'grid',
                        gridTemplateColumns: 'repeat(5, 1fr)',
                        gap: '6px',
                        alignContent: 'flex-start',
                        overflowY: 'auto',
                        padding: '12px',
                        backgroundColor: 'rgba(255,255,255,0.1)',
                        borderRadius: '20px'
                    }}>
                        {allRooms.map(room => (
                            <div key={room} style={{
                                background: !isCurrentOrFuture ? '#fff' : '#ffcc00',
                                padding: '8px 0',
                                borderRadius: '8px',
                                textAlign: 'center',
                                fontSize: '11px',
                                fontWeight: 'bold'
                            }}>
                                {room}
                            </div>
                        ))}
                    </div>

                    {/* RIGHT */}
                    <div style={{
                        flex: 1,
                        display: 'flex',
                        flexDirection: 'column',
                        backgroundColor: '#fff',
                        borderRadius: '25px',
                        padding: '25px', // 🔽 giảm từ 40
                        minHeight: 0 // ✅ QUAN TRỌNG
                    }}>

                        <h1 style={{
                            fontSize: '40px', // 🔽 giảm từ 60
                            margin: '0 0 20px 0',
                            color: '#8b5e5e',
                            flexShrink: 0
                        }}>
                            THÁNG: {selectedMonth}/{selectedYear}
                        </h1>

                        <div style={{
                            fontSize: '18px',
                            marginBottom: '20px',
                            flexShrink: 0
                        }}>
                            <b>Tổng tiền:</b>{" "}
                            <span style={{
                                color: totalReceived > 0 ? '#28a745' : '#999',
                                fontSize: '24px'
                            }}>
                                {totalReceived.toLocaleString()}đ
                            </span>
                        </div>

                        {/* TABLE SCROLL */}
                        <div style={{
                            flex: 1,
                            overflowY: 'auto',
                            border: '1px solid #eee',
                            borderRadius: '15px',
                            minHeight: 0 // ✅ QUAN TRỌNG NHẤT
                        }}>
                            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                <thead style={{
                                    position: 'sticky',
                                    top: 0,
                                    background: '#fff'
                                }}>
                                    <tr>
                                        <th style={{ padding: '10px' }}>Phòng</th>
                                        <th style={{ padding: '10px' }}>Tiền</th>
                                        <th style={{ padding: '10px' }}>Nội dung</th>
                                        <th style={{ padding: '10px' }}>Thời gian</th>
                                    </tr>
                                </thead>

                                <tbody>
                                    {!isCurrentOrFuture ? (
                                        allRooms.map(room => (
                                            <tr key={room}>
                                                <td style={{ padding: '10px' }}>{room}</td>
                                                <td style={{ padding: '10px', color: 'green' }}>5.000.000đ</td>
                                                <td style={{ padding: '10px' }}>Tiền phòng</td>
                                                <td style={{ padding: '10px' }}>01/{selectedMonth}/{selectedYear}</td>
                                            </tr>
                                        ))
                                    ) : (
                                        <tr>
                                            <td colSpan="4" style={{
                                                textAlign: 'center',
                                                padding: '50px',
                                                color: '#aaa'
                                            }}>
                                                Chưa có dữ liệu
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>

                    </div>
                </div>
            </div>
        </div>
    );
};

export default QuanLyHoaDon;
